<script setup lang="ts">
import { Plus, Refresh } from '@element-plus/icons-vue'
import { ElMessage } from 'element-plus'
import { computed, onMounted, reactive, ref } from 'vue'

import { api } from '../api/client'
import PageHeader from '../components/PageHeader.vue'
import StatusTag from '../components/StatusTag.vue'
import { useSessionStore } from '../stores/session'

const session=useSessionStore();const tab=ref('users');const loading=ref(false);const users=ref<any[]>([]);const members=ref<any[]>([]);const budget=ref<any>({});const models=ref<any>({});const mcp=ref<any>({});const dialog=ref('')
const userForm=reactive({username:'',password:'',role:'design_engineer'});const projectForm=reactive({name:''});const memberForm=reactive({user_id:'',role:'design_engineer'});const budgetForm=reactive({daily_token_limit:0,monthly_cost_limit_micros:0,max_concurrent_reviews:3,expected_lock_version:1})
const costLimit=computed(()=>((budget.value.monthly_cost_limit_micros||0)/1_000_000).toFixed(2))
async function load(){loading.value=true;try{const responses=await Promise.all([api.get('/api/v1/auth/users'),api.get(`/api/v1/projects/${session.currentProjectId}/members`),api.get(`/api/v1/projects/${session.currentProjectId}/budget`),api.get('/api/v1/model-capabilities'),api.get('/api/v1/integrations/mcp')]);[users.value,members.value,budget.value,models.value,mcp.value]=responses.map(r=>r.data);Object.assign(budgetForm,{daily_token_limit:budget.value.daily_token_limit,monthly_cost_limit_micros:budget.value.monthly_cost_limit_micros,max_concurrent_reviews:budget.value.max_concurrent_reviews,expected_lock_version:budget.value.lock_version})}catch(e){ElMessage.error(e instanceof Error?e.message:'管理数据加载失败')}finally{loading.value=false}}
async function createUser(){try{await api.post('/api/v1/auth/users',userForm);ElMessage.success('用户已创建');dialog.value='';await load()}catch(e){ElMessage.error(e instanceof Error?e.message:'创建失败')}}
async function createProject(){try{await api.post('/api/v1/projects',projectForm);ElMessage.success('项目已创建');dialog.value='';await session.bootstrap();await load()}catch(e){ElMessage.error(e instanceof Error?e.message:'创建失败')}}
async function addMember(){try{await api.post(`/api/v1/projects/${session.currentProjectId}/members`,memberForm);ElMessage.success('项目成员已更新');dialog.value='';await load()}catch(e){ElMessage.error(e instanceof Error?e.message:'更新失败')}}
async function updateBudget(){try{await api.patch(`/api/v1/projects/${session.currentProjectId}/budget`,budgetForm);ElMessage.success('预算已更新');await load()}catch(e:any){if(e.status===409)await load();ElMessage.error(e instanceof Error?e.message:'预算更新失败')}}
async function validateReranker(){try{const {data}=await api.post('/api/v1/model-capabilities/reranker/validate');ElMessage.success(`Reranker 验证通过，耗时 ${Math.round(data.latency_ms||0)}ms`)}catch(e){ElMessage.error(e instanceof Error?e.message:'验证失败')}}
onMounted(load)
</script>
<template><PageHeader title="系统管理" description="管理用户、项目、预算、模型策略和外部 AI 接入"><el-button :icon="Refresh" @click="load">刷新</el-button></PageHeader><section class="section"><el-tabs v-model="tab" class="admin-tabs"><el-tab-pane label="用户与成员" name="users"><div class="toolbar"><el-button type="primary" :icon="Plus" @click="dialog='user'">创建用户</el-button><el-button :icon="Plus" @click="dialog='member'">添加项目成员</el-button><el-button @click="dialog='project'">新建项目</el-button></div><el-table v-loading="loading" :data="users"><el-table-column prop="username" label="用户名"/><el-table-column prop="role" label="全局角色"/><el-table-column prop="is_active" label="状态"><template #default="s"><StatusTag :status="s.row.is_active?'active':'archived'"/></template></el-table-column><el-table-column prop="created_at" label="创建时间"/></el-table><h3>当前项目成员</h3><el-table :data="members"><el-table-column prop="username" label="用户名"/><el-table-column prop="global_role" label="全局角色"/><el-table-column prop="project_role" label="项目角色"/><el-table-column prop="is_active" label="状态"><template #default="s"><StatusTag :status="s.row.is_active?'active':'archived'"/></template></el-table-column></el-table></el-tab-pane><el-tab-pane label="项目预算" name="budget"><div class="budget-summary"><div><span>今日已用 Token</span><strong>{{budget.used_tokens||0}}</strong></div><div><span>预留 Token</span><strong>{{budget.reserved_tokens||0}}</strong></div><div><span>月度成本上限</span><strong>¥ {{costLimit}}</strong></div></div><el-form label-position="top" class="budget-form"><el-form-item label="每日 Token 上限"><el-input-number v-model="budgetForm.daily_token_limit" :min="10000" :step="10000"/></el-form-item><el-form-item label="月度估算成本上限（微元）"><el-input-number v-model="budgetForm.monthly_cost_limit_micros" :min="0" :step="1000000"/></el-form-item><el-form-item label="最大并发审查"><el-input-number v-model="budgetForm.max_concurrent_reviews" :min="1" :max="100"/></el-form-item><el-button type="primary" @click="updateBudget">保存预算</el-button></el-form></el-tab-pane><el-tab-pane label="模型与 MCP" name="models"><div class="integration-grid"><div><h3>模型策略</h3><p>Chat：{{models.active?.chat?.model||models.chat?.model||'-'}}</p><p>Embedding：{{models.active?.embedding?.model||models.embedding?.model||'-'}}</p><p>Reranker：{{models.active?.reranker?.model||models.reranker?.model||'-'}}</p><el-button @click="validateReranker">验证 Reranker</el-button></div><div><h3>MCP 外部接入</h3><p><StatusTag :status="mcp.healthy?'completed':'failed'"/> {{mcp.endpoint}}</p><p>SDK {{mcp.sdk_version}} · {{mcp.tools}} Tools · {{mcp.resources}} Resources</p><p class="muted">仅向外部 AI Host 暴露 public 资料，不参与内部 Agent 调度。</p></div></div></el-tab-pane></el-tabs></section>
<el-dialog v-model="dialog" :title="dialog==='user'?'创建企业用户':dialog==='member'?'添加项目成员':'新建项目'" width="480px"><el-form v-if="dialog==='user'" label-position="top"><el-form-item label="用户名"><el-input v-model="userForm.username"/></el-form-item><el-form-item label="密码"><el-input v-model="userForm.password" type="password" show-password/></el-form-item><el-form-item label="角色"><el-select v-model="userForm.role"><el-option label="设计工程师" value="design_engineer"/><el-option label="膜材采购" value="material_procurement"/><el-option label="项目审核人" value="reviewer"/><el-option label="管理员" value="admin"/></el-select></el-form-item></el-form><el-form v-else-if="dialog==='member'" label-position="top"><el-form-item label="用户"><el-select v-model="memberForm.user_id" filterable><el-option v-for="u in users" :key="u.id" :label="u.username" :value="u.id"/></el-select></el-form-item><el-form-item label="项目角色"><el-select v-model="memberForm.role"><el-option label="设计工程师" value="design_engineer"/><el-option label="膜材采购" value="material_procurement"/><el-option label="项目审核人" value="reviewer"/><el-option label="管理员" value="admin"/></el-select></el-form-item></el-form><el-form v-else label-position="top"><el-form-item label="项目名称"><el-input v-model="projectForm.name"/></el-form-item></el-form><template #footer><el-button @click="dialog=''">取消</el-button><el-button type="primary" @click="dialog==='user'?createUser():dialog==='member'?addMember():createProject()">确认</el-button></template></el-dialog></template>
<style scoped>.admin-tabs{padding:0 18px 20px}.admin-tabs :deep(.el-tabs__content){padding-top:8px}.budget-summary{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-bottom:20px}.budget-summary>div{padding:16px;border:1px solid #dce3e8}.budget-summary span{display:block;color:#687784;font-size:12px}.budget-summary strong{display:block;margin-top:8px;font-size:22px}.budget-form{max-width:520px}.integration-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.integration-grid>div{padding:18px;border:1px solid #dce3e8;border-radius:4px}@media(max-width:700px){.budget-summary,.integration-grid{grid-template-columns:1fr}}</style>
